package com.franco.desco.adapter.in.web.property;
import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.property.PropertyCommands;import com.franco.desco.application.property.port.in.PropertyUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/predios") @Tag(name="Predios",description="Gestión de predios, ubicación, versiones y titularidad.") @SecurityRequirement(name=OpenApiConstants.BEARER_AUTH) @Validated public class PropertyController{private final PropertyUseCase u;private final PropertyWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public PropertyController(PropertyUseCase u,PropertyWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping @PreAuthorize("@permissionGuard.has(authentication,'PREDIOS_LISTAR')") @Operation(operationId="prediosListar",summary="Listar predios") public ResponseEntity<ApiResponse<PageResponse<PropertyResponses.Summary>>>list(@RequestParam(required=false)String buscar,@RequestParam(required=false)Long socioId,@RequestParam(required=false)String distritoCodigo,@RequestParam(required=false)Boolean soloActivos,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,buscar,socioId,distritoCodigo,soloActivos),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}") @PreAuthorize("@permissionGuard.has(authentication,'PREDIOS_VER')") @Operation(operationId="prediosVer",summary="Ver expediente del predio") public ResponseEntity<ApiResponse<PropertyResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new PropertyCommands.GetProperty(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'PREDIOS_CREAR')") @Operation(operationId="prediosCrear",summary="Registrar predio") public ResponseEntity<ApiResponse<PropertyResponses.Created>>create(@Valid@RequestBody PropertyRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(map.command(q),ids.resolve(a),meta.resolve(r)),r,PropertyResponses.Created::new);}
 @PutMapping("/{id}") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'PREDIOS_EDITAR')") @Operation(operationId="prediosEditar",summary="Editar predio") public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody PropertyRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(map.command(id,q),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/retirar") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'PREDIOS_RETIRAR')") @Operation(operationId="prediosRetirar",summary="Retirar predio") public ResponseEntity<ApiResponse<Void>>retire(@PathVariable Long id,@Valid@RequestBody PropertyRequests.Retire q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.retire(new PropertyCommands.RetireProperty(id,q.fechaRetiro(),q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
}
